def load_environment() -> None:
    load_dotenv()

    try:
        secrets = st.secrets
    except Exception:
        secrets = {}

    for key in ("GROQ_API_KEY", "HF_TOKEN"):
        try:
            value = str(
                secrets.get(
                    key,
                    "",
                )
            ).strip()
        except Exception:
            value = ""

        if value and not os.getenv(key):
            os.environ[key] = value


load_environment()

if not os.getenv("GROQ_API_KEY"):
    st.error(
        "GROQ_API_KEY is missing. Add it to .env locally or "
        "to Streamlit Secrets when deployed."
    )
    st.stop()


