def initialize_session_state() -> None:
    for key, default_value in SESSION_DEFAULTS.items():
        if key not in st.session_state:
            st.session_state[key] = copy.deepcopy(
                default_value
            )


def detect_language(text: str) -> str:
    arabic_count = len(
        re.findall(
            r"[\u0600-\u06FF]",
            text or "",
        )
    )

    english_count = len(
        re.findall(
            r"[A-Za-z]",
            text or "",
        )
    )

    return (
        "Arabic"
        if arabic_count >= english_count
        else "English"
    )


def safe_html(value: object) -> str:
    return html.escape(
        str(value or ""),
        quote=True,
    )


def render_inline_text(value: str) -> str:
    escaped = safe_html(
        value.strip()
    )

    escaped = re.sub(
        r"\*\*(.+?)\*\*",
        r"<strong>\1</strong>",
        escaped,
    )

    escaped = re.sub(
        r"\s*\[SOURCE\s+\d+\]",
        "",
        escaped,
        flags=re.IGNORECASE,
    )

    return escaped.strip()


def parse_markdown_table(
    lines: list[str],
    start_index: int,
) -> tuple[str, int] | None:
    if start_index + 1 >= len(lines):
        return None

    header_line = lines[start_index].strip()
    separator_line = lines[start_index + 1].strip()

    if (
        "|" not in header_line
        or not re.fullmatch(
            r"\s*\|?[\s:|-]+\|[\s:|-|]*\|?\s*",
            separator_line,
        )
    ):
        return None

    headers = [
        cell.strip()
        for cell in header_line.strip("|").split("|")
    ]

    table_rows: list[list[str]] = []
    index = start_index + 2

    while index < len(lines):
        row_line = lines[index].strip()

        if not row_line or "|" not in row_line:
            break

        cells = [
            cell.strip()
            for cell in row_line.strip("|").split("|")
        ]

        if len(cells) == len(headers):
            table_rows.append(
                cells
            )

        index += 1

    if not table_rows:
        return None

    header_html = "".join(
        f"<th>{render_inline_text(header)}</th>"
        for header in headers
    )

    body_rows: list[str] = []

    for row in table_rows:
        cells_html = "".join(
            (
                f'<td data-label="{safe_html(headers[cell_index])}">'
                f"{render_inline_text(cell)}"
                "</td>"
            )
            for cell_index, cell in enumerate(row)
        )

        body_rows.append(
            f"<tr>{cells_html}</tr>"
        )

    table_html = (
        '<div class="guidance-table-wrap">'
        '<table class="guidance-table">'
        f"<thead><tr>{header_html}</tr></thead>"
        f"<tbody>{''.join(body_rows)}</tbody>"
        "</table>"
        "</div>"
    )

    return table_html, index


def answer_to_html(answer: str) -> str:
    lines = answer.splitlines()
    output: list[str] = []
    paragraph_buffer: list[str] = []
    bullet_buffer: list[str] = []
    heading_count = 0
    index = 0

    def flush_paragraph() -> None:
        if not paragraph_buffer:
            return

        paragraph = " ".join(
            part.strip()
            for part in paragraph_buffer
            if part.strip()
        )

        if paragraph:
            output.append(
                '<p class="answer-paragraph">'
                f"{render_inline_text(paragraph)}"
                "</p>"
            )

        paragraph_buffer.clear()

    def flush_bullets() -> None:
        if not bullet_buffer:
            return

        list_items = "".join(
            "<li>"
            f"{render_inline_text(item)}"
            "</li>"
            for item in bullet_buffer
        )

        output.append(
            '<ul class="answer-list">'
            f"{list_items}"
            "</ul>"
        )

        bullet_buffer.clear()

    while index < len(lines):
        line = lines[index].strip()

        table_result = parse_markdown_table(
            lines,
            index,
        )

        if table_result is not None:
            flush_paragraph()
            flush_bullets()
            table_html, index = table_result
            output.append(
                table_html
            )
            continue

        if not line:
            flush_paragraph()
            flush_bullets()
            index += 1
            continue

        heading_match = re.match(
            r"^(#{1,4})\s+(.+)$",
            line,
        )

        if heading_match:
            flush_paragraph()
            flush_bullets()
            heading_count += 1

            css_class = (
                "answer-main-title"
                if heading_count == 1
                else "answer-section-title"
            )

            output.append(
                f'<h2 class="{css_class}">'
                f"{render_inline_text(heading_match.group(2))}"
                "</h2>"
            )

            index += 1
            continue

        bullet_match = re.match(
            r"^[-*]\s+(.+)$",
            line,
        )

        if bullet_match:
            flush_paragraph()
            bullet_buffer.append(
                bullet_match.group(1)
            )
            index += 1
            continue

        flush_bullets()
        paragraph_buffer.append(
            line
        )
        index += 1

    flush_paragraph()
    flush_bullets()

    return "".join(output)


def build_profile_context(
    child_name: str,
    age: int,
    gender: str,
    school_class: str,
    height: int,
    weight: int,
    activity_level: str,
    health_conditions: list[str],
    allergies: list[str],
    disliked_foods: list[str],
    other_disliked_foods: str,
) -> tuple[str, float]:
    bmi = (
        weight / ((height / 100) ** 2)
        if height > 0 and weight > 0
        else 0.0
    )

    all_disliked_foods = [
        item
        for item in disliked_foods
        if str(item).strip()
    ]

    if other_disliked_foods.strip():
        all_disliked_foods.append(
            other_disliked_foods.strip()
        )

    profile_lines = [
        f"Child name: {child_name.strip() or 'Not provided'}",
        f"Age: {age if age > 0 else 'Not provided'}",
        (
            f"Gender: {gender}"
            if gender != "Not selected"
            else "Gender: Not provided"
        ),
        (
            f"School class: {school_class.strip()}"
            if school_class.strip()
            else "School class: Not provided"
        ),
        (
            f"Height: {height} cm"
            if height > 0
            else "Height: Not provided"
        ),
        (
            f"Weight: {weight} kg"
            if weight > 0
            else "Weight: Not provided"
        ),
        (
            f"BMI: {bmi:.1f}"
            if bmi > 0
            else "BMI: Not available"
        ),
        f"Activity level: {activity_level}",
        (
            "Health conditions: "
            + (
                ", ".join(health_conditions)
                if health_conditions
                else "None reported"
            )
        ),
        (
            "Allergies and intolerances: "
            + (
                ", ".join(allergies)
                if allergies
                else "None reported"
            )
        ),
        (
            "Disliked foods: "
            + (
                ", ".join(all_disliked_foods)
                if all_disliked_foods
                else "None reported"
            )
        ),
    ]

    return "\n".join(profile_lines), bmi


def build_effective_question(
    user_question: str,
    profile: str,
) -> str:
    requested_language = detect_language(
        user_question
    )

    return (
        "USER QUESTION:\n"
        f"{user_question.strip()}\n\n"
        "RESPONSE LANGUAGE:\n"
        f"{requested_language}\n\n"
        "CHILD PROFILE AUTOMATICALLY SUPPLIED BY THE APPLICATION:\n"
        f"{profile}\n\n"
        "Answer the user question directly. Do not ask the user to repeat "
        "any profile field. Use practical metric and household measurements "
        "only. Never use ounces, fluid ounces, or pounds."
    )


def render_answer(
    result: dict[str, Any],
) -> None:
    answer = str(
        result.get(
            "answer",
            "",
        )
    ).strip()

    status = str(
        result.get(
            "status",
            "unknown",
        )
    )

    direction = (
        "rtl"
        if detect_language(answer) == "Arabic"
        else "ltr"
    )

    status_label = (
        "Grounded guidance"
        if status == "success"
        else "Limited evidence"
    )

    st.markdown(
        '<div class="answer-header">'
        '<h2 class="answer-heading">Nutrition Guidance</h2>'
        f'<span class="status-chip">{safe_html(status_label)}</span>'
        "</div>",
        unsafe_allow_html=True,
    )

    if not answer:
        st.warning(
            "No answer was generated."
        )
        return

    st.markdown(
        '<div class="answer-card">'
        f'<div class="structured-answer" dir="{direction}">'
        f"{answer_to_html(answer)}"
        "</div>"
        "</div>",
        unsafe_allow_html=True,
    )


